/**
 * Select the most recent messages by timestamp.
 *
 * @param {Array<{id: *, timestamp: number}>} messages - Input messages (not mutated).
 * @param {number} limit - Maximum number of messages to return (non-negative integer).
 * @returns {Array<{id: *, timestamp: number}>} Up to `limit` messages, sorted by
 *   timestamp descending; ties preserve input order.
 * @throws {RangeError} If `limit` is not a non-negative integer.
 */
export function latestMessages(messages, limit) {
  if (!Number.isInteger(limit) || limit < 0) {
    throw new RangeError('limit must be a non-negative integer');
  }

  if (messages.length === 0 || limit === 0) {
    return [];
  }

  // Decorate with original index so ties keep input order.
  const indexed = messages.map((message, index) => ({ message, index }));

  indexed.sort((a, b) => {
    const diff = b.message.timestamp - a.message.timestamp;
    return diff !== 0 ? diff : a.index - b.index;
  });

  return indexed.slice(0, limit).map((entry) => entry.message);
}
